import json,pathlib
p=pathlib.Path('acceptance/reports/m21-acceptance.json');data=json.loads(p.read_text());assert set(data)==set(map(str,range(2,8))) and all(r.get('passed') is True for r in data.values())
apks=json.loads(pathlib.Path('artifacts/docs/m21-apk-sizes.json').read_text());assert {r['abi'] for r in apks}=={'arm64-v8a','x86_64'}
lines=['修复与根因：','- 常驻秒连与首帧缓存：启动链等待非聊天初始化，界面此前依赖内核会话列表。','- 即时发送：同步快照和模型网络审批阻塞主请求，现改为直接发送及持久化等待队列。','- 历史时间：回放以当前时间覆盖列表，现读取最后原始消息时间；解析失败显示未知。','- ChatGPT 订阅（实验）：加入 Codex OAuth/PKCE、Keystore 与原 dsh Codex 流式传输，无中转。','','七项验收全部通过（AOSP API 36 x86_64 模拟器）：',f"1. 双 ABI 构建、原证书 e20b…8fd1；APK 字节数：{', '.join(r['abi']+' '+str(r['bytes']) for r in apks)}。",f"2. 200→201 覆盖：保留 {data['2']['preservedSessions']} 个会话、配置及 Keystore 凭据。",f"3. 常驻重开：{data['3']['warmReopenMs']} ms；内核 PID 不变。",f"4. 首帧 {data['4']['activityFirstDrawMs']} ms；缓存 {data['4']['cachedSessionsAtFirstDraw']} 个会话；输入可用，等待消息自动发出。",f"5. 点击→首个 HTTP：{data['5']['clickToFirstHttpMs']} ms；时钟误差 {data['5']['clockUncertaintyMs']} ms。",f"6. 历史显示：{'、'.join(data['6']['labels'])}；冷启动及连接后原时间与 JSONL 不变。",f"7. mock OAuth/PKCE、回调、流式正文/思考、刷新及额度错误通过；刷新 {data['7']['refreshes']} 次，输入 token 实报 {data['7']['reportedInputTokens']}。",'','真实账号及订阅额度由用户在手机上测试。下载匹配 ABI 的 APK 直接覆盖安装。']
pathlib.Path('build').mkdir(exist_ok=True);pathlib.Path('build/m21-release-notes.md').write_text('\n'.join(lines)+'\n')
